// processPayment.js
const { validateOrder } = require('./validateOrder');
const { chargeCard } = require('./chargeCard');
const { sendReceipt } = require('./sendReceipt');
const { PaymentError, PaymentProcessingError } = require('./errors');

async function processPayment(order) {
  try {
    const validOrder = await validateOrder(order);
    const chargeResult = await chargeCard(validOrder);
    const receipt = await sendReceipt(chargeResult);
    return receipt;
  } catch (err) {
    if (err instanceof PaymentError) {
      console.warn("Payment error: " + err.message);
      throw err;
    } else {
      const wrappedErr = new PaymentProcessingError("Payment processing failed: " + err.message, err);
      throw wrappedErr;
    }
  }
}
module.exports = { processPayment };

