import re

class Token:
    def __init__(self, type_, value=None):
        self.type = type_  # 'NUMBER', 'OP', 'LPAREN', 'RPAREN'
        self.value = value

def tokenize(expr):
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i].isdigit():
            start = i
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                i += 1
            num_str = expr[start:i]
            if num_str.count('.') > 1:
                raise ValueError(f"Invalid number: {num_str}")
            tokens.append(Token('NUMBER', float(num_str)))
            continue
        if expr[i] in '+-*/':
            tokens.append(Token('OP', expr[i]))
            i += 1
            continue
        if expr[i] == '(':
            tokens.append(Token('LPAREN'))
            i += 1
            continue
        if expr[i] == ')':
            tokens.append(Token('RPAREN'))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {expr[i]}")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def parse_expression(self):
        return self.parse_term()

    def parse_term(self):
        value = self.parse_factor()
        while self.peek() and self.peek().type == 'OP' and self.peek().value in '+-':
            op = self.consume()
            right = self.parse_factor()
            if op.value == '+':
                value += right
            else:
                value -= right
        return value

    def parse_factor(self):
        value = self.parse_primary()
        while self.peek() and self.peek().type == 'OP' and self.peek().value in '*/':
            op = self.consume()
            right = self.parse_primary()
            if op.value == '*':
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                value /= right
        return value

    def parse_primary(self):
        tok = self.peek()
        if not tok:
            raise ValueError("Unexpected end of expression")
        if tok.type == 'NUMBER':
            self.consume()
            return tok.value
        if tok.type == 'LPAREN':
            self.consume()
            value = self.parse_expression()
            if self.peek() is None or self.peek().type != 'RPAREN':
                raise ValueError("Mismatched parentheses: missing ')'")
            self.consume()
            return value
        raise ValueError(f"Unexpected token: {tok.type} {tok.value}")

def evaluate(expression: str) -> float:
    try:
        tokens = tokenize(expression)
        if not tokens:
            raise ValueError("Empty expression")
        parser = Parser(tokens)
        result = parser.parse_expression()
        if parser.pos != len(tokens):
            raise ValueError("Unexpected trailing tokens")
        return result
    except (ValueError, ZeroDivisionError) as e:
        raise
